import{_ as a,o,c as r,ag as e}from"./chunks/framework.D2veAa-g.js";const u=JSON.parse('{"title":"架构师-备考 综合知识-架构设计-软件架构演化与维护","description":"","frontmatter":{"title":"架构师-备考 综合知识-架构设计-软件架构演化与维护"},"headers":[],"relativePath":"综合知识/架构设计/软件架构演化与维护.md","filePath":"综合知识/架构设计/软件架构演化与维护.md","lastUpdated":null}'),d={name:"综合知识/架构设计/软件架构演化与维护.md"};function l(h,t,n,s,i,b){return o(),r("div",null,[...t[0]||(t[0]=[e('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 软件架构演化定义与三要素（组件/连接件/约束）</li><li>[ ] 静态演化 vs 动态演化分类</li><li>[ ] 静态演化五步骤流程</li><li>[ ] 动态演化三个级别（交互/结构/架构）</li><li>[ ] 演化四时期（设计时/运行前/有限制运行时/运行时）</li><li>[ ] 演化五大原则（模块独立/主体维持/进度可控/成本控制/风险可控）</li><li>[ ] 演化评估方法（演化已知 vs 演化未知）</li><li>[ ] 面向对象演化过程（对象/消息/复合片段/约束）</li><li>[ ] 软件维护四类型（纠错性/适应性/完善性/预防性）</li><li>[ ] 架构知识管理/版本管理/修改管理</li><li>[ ] 可维护性度量（圈复杂度/耦合度/扇入扇出度/模块响应）</li><li>[ ] 大型网站架构演化路径</li></ul><hr><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、软件架构演化基础" tabindex="-1">一、软件架构演化基础 <a class="header-anchor" href="#一、软件架构演化基础" aria-label="Permalink to &quot;一、软件架构演化基础&quot;">​</a></h3><blockquote><p>🎯 软件架构定义 SA = {组件，连接件，约束}，演化就是这三个要素的变化。演化涵盖需求获取、建模、实现阶段，<strong>不包括测试阶段</strong>。</p></blockquote><p><strong>三要素演化的具体表现：</strong></p><table tabindex="0"><thead><tr><th>要素</th><th>演化体现</th></tr></thead><tbody><tr><td><strong>组件</strong></td><td>模块的增加、删除或修改</td></tr><tr><td><strong>连接件</strong></td><td>组件间交互消息的增加、删除或改变</td></tr><tr><td><strong>约束</strong></td><td>组件间拓扑关系和配置的调整</td></tr></tbody></table><hr><h3 id="二、演化分类" tabindex="-1">二、演化分类 <a class="header-anchor" href="#二、演化分类" aria-label="Permalink to &quot;二、演化分类&quot;">​</a></h3><blockquote><p>🎯 区分静态/动态的核心标准：是否在系统运行时期发生。</p></blockquote><h4 id="_2-1-静态演化-vs-动态演化" tabindex="-1">2.1 静态演化 vs 动态演化 <a class="header-anchor" href="#_2-1-静态演化-vs-动态演化" aria-label="Permalink to &quot;2.1 静态演化 vs 动态演化&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>典型场景</th></tr></thead><tbody><tr><td><strong>静态演化</strong></td><td>系统停止运行后进行修改和重构</td><td>版本升级、功能新增</td></tr><tr><td><strong>动态演化</strong></td><td>系统在运行过程中动态改变结构和行为</td><td>热更新、弹性伸缩</td></tr></tbody></table><h4 id="_2-2-静态演化五步骤" tabindex="-1">2.2 静态演化五步骤 <a class="header-anchor" href="#_2-2-静态演化五步骤" aria-label="Permalink to &quot;2.2 静态演化五步骤&quot;">​</a></h4><blockquote><p>🎯 软件理解是静态演化中查阅文档、分析架构、识别系统组成元素的关键步骤。</p></blockquote><ol><li><strong>需求变更分析</strong> — 识别变更需求</li><li><strong>软件理解</strong> — 查阅文档、分析架构、识别系统组成元素及相互关系</li><li><strong>演化计划</strong> — 制定修改方案</li><li><strong>系统重构</strong> — 实施修改</li><li><strong>系统测试</strong> — 验证修改结果</li></ol><h4 id="_2-3-动态演化三个级别" tabindex="-1">2.3 动态演化三个级别 <a class="header-anchor" href="#_2-3-动态演化三个级别" aria-label="Permalink to &quot;2.3 动态演化三个级别&quot;">​</a></h4><blockquote><p>🎯 难度递增：交互动态性 &lt; 结构动态性 &lt; 架构动态性。拓扑结构改变是最复杂且影响最大的变化。</p></blockquote><table tabindex="0"><thead><tr><th>级别</th><th>能力</th><th>示例</th></tr></thead><tbody><tr><td><strong>交互动态性</strong></td><td>动态改变数据交互模式和通信协议</td><td>协议版本协商</td></tr><tr><td><strong>结构动态性</strong></td><td>动态改变组件实例及其连接关系</td><td>运行时添加/删除构件实例</td></tr><tr><td><strong>架构动态性</strong></td><td>允许对架构基本构造进行变动，如定义新的组件类型</td><td>热加载新的组件模板</td></tr></tbody></table><h4 id="_2-4-演化四个时期" tabindex="-1">2.4 演化四个时期 <a class="header-anchor" href="#_2-4-演化四个时期" aria-label="Permalink to &quot;2.4 演化四个时期&quot;">​</a></h4><table tabindex="0"><thead><tr><th>时期</th><th>特点</th></tr></thead><tbody><tr><td><strong>设计时演化</strong></td><td>发生在编码和编译前，修改设计模型</td></tr><tr><td><strong>运行前演化</strong></td><td>发生在编译之后、执行之前，系统需有<strong>添加和删除组件</strong>的机制</td></tr><tr><td><strong>有限制运行时演化</strong></td><td>运行时但只能修改预设的可变部分</td></tr><tr><td><strong>运行时演化</strong></td><td>完全动态地在运行过程中改变结构和行为</td></tr></tbody></table><blockquote><p>⚠️ 静态演化需求分为两类：<strong>设计时演化需求</strong>和<strong>运行前演化需求</strong>。</p></blockquote><hr><h3 id="三、演化五大原则" tabindex="-1">三、演化五大原则 <a class="header-anchor" href="#三、演化五大原则" aria-label="Permalink to &quot;三、演化五大原则&quot;">​</a></h3><h4 id="_3-1-模块独立演化原则" tabindex="-1">3.1 模块独立演化原则 <a class="header-anchor" href="#_3-1-模块独立演化原则" aria-label="Permalink to &quot;3.1 模块独立演化原则&quot;">​</a></h4><blockquote><p>🎯 各模块自身演化相互独立，影响范围可控。</p></blockquote><h4 id="_3-2-主体维持原则" tabindex="-1">3.2 主体维持原则 <a class="header-anchor" href="#_3-2-主体维持原则" aria-label="Permalink to &quot;3.2 主体维持原则&quot;">​</a></h4><blockquote><p>🎯 AIG（对称稳定增长）= 主体规模的变更量 / 主体的规模。要求平均增量增长保持平稳。</p></blockquote><h4 id="_3-3-进度可控原则" tabindex="-1">3.3 进度可控原则 <a class="header-anchor" href="#_3-3-进度可控原则" aria-label="Permalink to &quot;3.3 进度可控原则&quot;">​</a></h4><blockquote><p>🎯 ttask = |Ttask - T&#39;task|，即演化任务的实际完成时间与预期完成时间的<strong>时间差绝对值</strong>。</p></blockquote><h4 id="_3-4-演化成本控制原则-ecc" tabindex="-1">3.4 演化成本控制原则（ECC） <a class="header-anchor" href="#_3-4-演化成本控制原则-ecc" aria-label="Permalink to &quot;3.4 演化成本控制原则（ECC）&quot;">​</a></h4><blockquote><p>🎯 CoE &lt;&lt; CoRD，即<strong>演化成本应明显小于重新开发成本</strong>。</p></blockquote><ul><li>CoE（Cost of Evolution）= 演化成本</li><li>CoRD（Cost of Re-Development）= 重新开发成本</li></ul><h4 id="_3-5-风险可控原则" tabindex="-1">3.5 风险可控原则 <a class="header-anchor" href="#_3-5-风险可控原则" aria-label="Permalink to &quot;3.5 风险可控原则&quot;">​</a></h4><blockquote><p>🎯 经济、时间、人力、技术和环境等<strong>多种风险</strong>都需要在可控范围内，不是只控制某一种。</p></blockquote><p>⚠️ 常见坑：选项中说&quot;只需要控制某一种风险&quot;就是错的。</p><hr><h3 id="四、演化评估方法" tabindex="-1">四、演化评估方法 <a class="header-anchor" href="#四、演化评估方法" aria-label="Permalink to &quot;四、演化评估方法&quot;">​</a></h3><blockquote><p>🎯 关键区分：演化过程已知 → 比较差异 + 分析质量变化；演化过程未知 → 逆向推测。</p></blockquote><table tabindex="0"><thead><tr><th>场景</th><th>评估方法</th><th>评估内容</th></tr></thead><tbody><tr><td><strong>演化过程已知</strong></td><td>对演化过程进行度量，比较架构内部结构差异以及外部质量属性变化</td><td>前后架构差异 + 质量属性变化</td></tr><tr><td><strong>演化过程未知</strong></td><td>根据架构演化前后的度量结果逆向推测架构发生的改变</td><td>逆向推测发生了什么变化</td></tr></tbody></table><hr><h3 id="五、面向对象软件架构演化" tabindex="-1">五、面向对象软件架构演化 <a class="header-anchor" href="#五、面向对象软件架构演化" aria-label="Permalink to &quot;五、面向对象软件架构演化&quot;">​</a></h3><h4 id="_5-1-对象演化" tabindex="-1">5.1 对象演化 <a class="header-anchor" href="#_5-1-对象演化" aria-label="Permalink to &quot;5.1 对象演化&quot;">​</a></h4><blockquote><p>🎯 AO操作（添加对象）一般在系统需要添加新对象实现新功能时发生。</p></blockquote><h4 id="_5-2-消息演化-三类" tabindex="-1">5.2 消息演化（三类） <a class="header-anchor" href="#_5-2-消息演化-三类" aria-label="Permalink to &quot;5.2 消息演化（三类）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>特征</th></tr></thead><tbody><tr><td>第1类</td><td>消息演化未涉及任何约束相关变化</td></tr><tr><td><strong>第2类</strong></td><td>删除的消息是某约束的内容之一，演化后约束不满足</td></tr><tr><td>第3类</td><td>改变消息的源或目标后产生新消息</td></tr></tbody></table><blockquote><p>🎯 第2类最需关注：删除消息导致约束不满足。</p></blockquote><h4 id="_5-3-复合片段演化" tabindex="-1">5.3 复合片段演化 <a class="header-anchor" href="#_5-3-复合片段演化" aria-label="Permalink to &quot;5.3 复合片段演化&quot;">​</a></h4><blockquote><p>🎯 复合片段是对象交互关系的控制描述，可表示不同场合的交互。FCC改变复合片段内部执行条件时，会影响所有符合条件的执行转移（不只是部分）。</p></blockquote><p>⚠️ 常见坑：选项说&quot;仅影响符合条件的执行转移&quot;是错误的，复合片段演化等价于消息序列演化。</p><h4 id="_5-4-约束演化" tabindex="-1">5.4 约束演化 <a class="header-anchor" href="#_5-4-约束演化" aria-label="Permalink to &quot;5.4 约束演化&quot;">​</a></h4><blockquote><p>🎯 对约束信息进行修改，可等同于<strong>删除原有约束并添加新约束</strong>。</p></blockquote><hr><h3 id="六、软件维护" tabindex="-1">六、软件维护 <a class="header-anchor" href="#六、软件维护" aria-label="Permalink to &quot;六、软件维护&quot;">​</a></h3><h4 id="_6-1-维护四种类型" tabindex="-1">6.1 维护四种类型 <a class="header-anchor" href="#_6-1-维护四种类型" aria-label="Permalink to &quot;6.1 维护四种类型&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>触发原因</th><th>关键词</th></tr></thead><tbody><tr><td><strong>纠错性维护</strong></td><td>修复发现的错误/缺陷</td><td>修复bug</td></tr><tr><td><strong>适应性维护</strong></td><td>适应软件运行<strong>环境的变化</strong></td><td>环境变化（OS、硬件升级）</td></tr><tr><td><strong>完善性维护</strong></td><td>用户提出的<strong>建设性意见</strong>，增加新功能</td><td>用户建议、功能增强</td></tr><tr><td><strong>预防性维护</strong></td><td>主动修改以预防潜在问题</td><td>提前预防</td></tr></tbody></table><blockquote><p>🎯 区分技巧：适应性=环境逼的；完善性=用户想要；纠错性=本身坏了。</p></blockquote><h4 id="_6-2-可维护性影响因素-七大因素" tabindex="-1">6.2 可维护性影响因素（七大因素） <a class="header-anchor" href="#_6-2-可维护性影响因素-七大因素" aria-label="Permalink to &quot;6.2 可维护性影响因素（七大因素）&quot;">​</a></h4><p>可理解性、可测试性、可修改性、可靠性、可移植性、可使用性、效率。</p><hr><h3 id="七、架构管理" tabindex="-1">七、架构管理 <a class="header-anchor" href="#七、架构管理" aria-label="Permalink to &quot;七、架构管理&quot;">​</a></h3><h4 id="_7-1-架构知识管理" tabindex="-1">7.1 架构知识管理 <a class="header-anchor" href="#_7-1-架构知识管理" aria-label="Permalink to &quot;7.1 架构知识管理&quot;">​</a></h4><blockquote><p>🎯 架构知识 = <strong>架构设计 + 架构设计决策</strong>。核心目标是对架构设计中隐含的决策来源进行文档化表示。</p></blockquote><h4 id="_7-2-架构版本管理" tabindex="-1">7.2 架构版本管理 <a class="header-anchor" href="#_7-2-架构版本管理" aria-label="Permalink to &quot;7.2 架构版本管理&quot;">​</a></h4><blockquote><p>🎯 为软件架构演化的版本演化控制、使用和评价等提供可靠依据。</p></blockquote><h4 id="_7-3-架构修改管理" tabindex="-1">7.3 架构修改管理 <a class="header-anchor" href="#_7-3-架构修改管理" aria-label="Permalink to &quot;7.3 架构修改管理&quot;">​</a></h4><blockquote><p>🎯 建立<strong>隔离区域</strong>的主要目的是减少修改对其他部分的影响。</p></blockquote><h4 id="_7-4-软件架构的核心作用-在维护视角" tabindex="-1">7.4 软件架构的核心作用（在维护视角） <a class="header-anchor" href="#_7-4-软件架构的核心作用-在维护视角" aria-label="Permalink to &quot;7.4 软件架构的核心作用（在维护视角）&quot;">​</a></h4><blockquote><p>🎯 软件架构是连接软件需求和设计、实现之间的<strong>桥梁</strong>。</p></blockquote><hr><h3 id="八、可维护性度量" tabindex="-1">八、可维护性度量 <a class="header-anchor" href="#八、可维护性度量" aria-label="Permalink to &quot;八、可维护性度量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>度量指标</th><th>含义</th></tr></thead><tbody><tr><td><strong>圈复杂度（CCN）</strong></td><td>代码逻辑复杂程度</td></tr><tr><td><strong>模块间耦合度（CBO）</strong></td><td>模块与其他模块交互的频繁程度</td></tr><tr><td><strong>扇入扇出度（FFC）</strong></td><td>模块被调用和调用其他模块的程度</td></tr><tr><td><strong>模块的响应（RFC）</strong></td><td>模块被调用的方法数量</td></tr></tbody></table><blockquote><p>🎯 CBO衡量耦合程度，是评估可维护性的核心指标。代码行数<strong>不属于</strong>可维护性度量的子度量指标。</p></blockquote><p>⚠️ 常见坑：代码行数（LOC）不是标准的可维护性度量指标。</p><hr><h3 id="九、大型网站系统架构演化路径" tabindex="-1">九、大型网站系统架构演化路径 <a class="header-anchor" href="#九、大型网站系统架构演化路径" aria-label="Permalink to &quot;九、大型网站系统架构演化路径&quot;">​</a></h3><blockquote><p>🎯 演化顺序（从简单到复杂）：单体架构 → 缓存 → 服务集群 → 数据库读写分离 → CDN/反向代理 → 分布式数据库 → NoSQL/搜索引擎 → 中台。</p></blockquote><p><strong>典型演进阶段：</strong></p><table tabindex="0"><thead><tr><th>阶段</th><th>解决问题</th><th>关键技术</th></tr></thead><tbody><tr><td>1. 单体架构</td><td>初始阶段</td><td>单服务器</td></tr><tr><td>2. 使用缓存</td><td>减轻数据库读压力</td><td>MemCache、Redis</td></tr><tr><td>3. 服务集群</td><td>高并发、高可用</td><td>负载均衡</td></tr><tr><td>4. 数据库读写分离</td><td>数据库性能瓶颈</td><td>主库写、从库读</td></tr><tr><td>5. CDN + 反向代理</td><td>用户访问延迟、响应速度</td><td>CDN内容分发</td></tr><tr><td>6. 分布式数据库</td><td>单数据库容量极限</td><td>分库分表</td></tr><tr><td>7. NoSQL + 搜索引擎</td><td>非结构化数据、全文搜索</td><td>Elasticsearch</td></tr><tr><td>8. 中台化</td><td>多业务线共享能力</td><td>业务中台</td></tr></tbody></table><h4 id="关键概念速记" tabindex="-1">关键概念速记 <a class="header-anchor" href="#关键概念速记" aria-label="Permalink to &quot;关键概念速记&quot;">​</a></h4><ul><li><strong>CDN</strong>：解决<strong>用户访问延迟</strong>，加速响应速度，改善用户体验</li><li><strong>反向代理负载均衡</strong>：基于<strong>应用层</strong>实现的负载均衡（区别于基于DNS的负载均衡）</li><li><strong>数据库读写分离</strong>：主库负责写、从库负责读</li><li><strong>分布式数据库系统</strong>：通常是最后采取的数据库拆分手段</li><li><strong>中台</strong>：作为所有项目的公共资源提供平台</li><li>Redis（vs MemCache）：支持复杂数据结构（list/set/hash）、支持持久化、支持事务（弱支持）；MemCache：只支持简单k-v、不支持持久化、不支持事务</li></ul><blockquote><p>🎯 缓存技术区别：MemCache = 简单k/v，无持久化；Redis = 复杂数据结构 + 持久化 + 弱事务。</p></blockquote>',82)])])}const q=a(d,[["render",l]]);export{u as __pageData,q as default};
